insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('d5d245e3-ba59-5d02-b9bd-b214f5dafa4d', '5c5f55d2-b389-5e93-94b9-3eb2897e1055', 'Any verb, any person', '**No es que** takes the subjunctive with every verb and every person: **no es que no me interese**, **no es que no me importe**, **no es que me caiga mal** — *it''s not that I don''t like him*; **no es que no queramos**, **no es que no podamos**.', 'draft'),
  ('cc5e231d-b0ac-5861-be50-d1802854aad9', '5c5f55d2-b389-5e93-94b9-3eb2897e1055', 'Saying no without quedar mal', 'Nobody wants to **quedar mal** — *come off as rude*. So you thank them for the **invitación**, blame a **compromiso** — *something already on*, and leave the door open: **la próxima voy**, **otro día**. And if they push: **no insistas, che**.', 'draft'),
  ('e7e97709-b1ce-5787-93fb-a7735a2015ce', 'd796fd3a-cc6b-531c-b6fa-3109c3f6c4fe', 'Your life, my life', 'The mixed conditional with *you*: **si hubieras estudiado medicina, ahora serías médico**; **si me hubieras hecho caso, no estarías así**. With *we*: **si hubiéramos ahorrado, ahora tendríamos para las vacaciones**.', 'draft'),
  ('5a7bee24-001f-5d37-813f-64d1da9b1600', 'd796fd3a-cc6b-531c-b6fa-3109c3f6c4fe', 'A esta altura…', '**A esta altura** — *by now* — is how porteños bring the other life into the present: **si me hubiera mudado a Córdoba, a esta altura estaría re tranquilo**. New participles: **mudado, aprendido, dejado, invertido**.', 'draft'),
  ('c8d4a413-653b-5e85-8421-f4a28a90ff0c', '52f4c57b-461b-5689-bc83-625e8445b0b2', 'We should have, they should have', 'The regret works for everyone: **tendríamos que haber salido antes**, **tendrían que haber avisado**. And the softest one of all: **me hubiera gustado** — *I''d have liked to*: **me hubiera gustado verte**.', 'draft'),
  ('54279426-a9ab-597a-90c9-2ebc30ce6253', '52f4c57b-461b-5689-bc83-625e8445b0b2', '¿Te arrepentís?', 'With *vos*: **¿te arrepentís?**; with *him*: **se arrepintió**. A chance you **dejaste pasar** — *let slip* — gets a **te lo perdiste** from your friends; a blunder is **metí la pata**. **Lamentablemente**, you can''t **volver atrás**.', 'draft'),
  ('79166998-d12f-521d-ac73-c6f3f7853dc7', '8096e043-1d54-5521-ac96-7cdb39c6e872', 'No es que no me interese', 'Any verb after **no es que** goes subjunctive: **no me interese**, **no queramos**, **me caiga mal**.', 'draft'),
  ('55b97bb7-34ad-5d9c-8a39-e9ca1dff6cbe', '8096e043-1d54-5521-ac96-7cdb39c6e872', 'Otra vida, otra oportunidad', '**Si hubieras estudiado, ahora serías…** — and the one you let slip: **me hubiera gustado**, **tendríamos que haber…**, **te lo perdiste**.', 'draft'),
  ('25238004-814b-58f4-824a-ded9fff9bc9e', '827ff70d-4671-51f6-a0aa-745cfebd058a', '-cito', 'Words ending in *-or*, *-ol*, *-e* take **-cito**: **calor → calorcito**, **sol → solcito**, **fresco → fresquito** (the *c* turns *qu*). Porteños talk about the weather almost only in diminutives: **hace fresquito**, **qué lindo calorcito**.', 'draft'),
  ('48fa40c1-c5f2-58f5-8669-4ba8e2da759c', '827ff70d-4671-51f6-a0aa-745cfebd058a', '-ito on everything', 'Nouns: **una cosita**, **un pedacito**, **un besito**. Adjectives: **calentito** — *nice and warm*; **cortito**; **igualito a su papá**; **solito** — *all by himself*. Adverbs: **tempranito**, **rapidito**. It agrees like any adjective: **una sopa calentita**.', 'draft'),
  ('83a1fba1-c4e8-509e-834e-ea0696869b8d', '28506229-594f-503e-80d4-5a3a1085320a', 'Lo que pasó fue que…', 'Tell it in the past: **lo que pasó fue que se cortó el subte**. Say what you meant: **lo que quiero decir es que…**. **Lo que más** — *what… most*: **lo que más me molestó fue eso**. And **en el fondo** — *deep down* — for the real reason under it.', 'draft'),
  ('e19109d4-b42a-551e-8023-98c286a43783', '28506229-594f-503e-80d4-5a3a1085320a', 'Lo mío, lo tuyo', '**Lo** turns anything into *the thing*: **lo tuyo es la cocina** — *your thing is cooking*; **lo mío** — *my thing*; **lo primero** — *the first thing*; **lo justo** — *just enough*. Giving up an argument: **lo que vos digas** or **lo que sea** — *whatever*.', 'draft'),
  ('a52eadb9-c139-52a4-b142-3865a13646ae', 'e3d036c1-9bf7-582a-8fdc-04202411acae', 'Como dice el dicho…', '**Como dice el dicho** — *as the saying goes* — and then the one that fits: **cada loco con su tema** — *to each their own*; **no hay dos sin tres** — *it happened twice, it''ll happen again*; **el que no llora no mama** — *the squeaky wheel gets the grease*.', 'draft'),
  ('c856ee20-16fd-55e2-88a7-bb617e0c577d', 'e3d036c1-9bf7-582a-8fdc-04202411acae', 'The ones grandma says', '**Más vale pájaro en mano que cien volando** — *a bird in the hand*; **a caballo regalado no se le miran los dientes**; **ojos que no ven, corazón que no siente**; **del dicho al hecho hay mucho trecho** — *easier said than done*. **El que se quema con leche, ve una vaca y llora** — *once bitten, twice shy*. And when someone walks in: **hablando del rey de Roma…**', 'draft'),
  ('cdacfa78-9d0a-503a-8012-a9d4b1dfa0d9', 'aca6a7bd-05eb-5bcb-a0c0-02cd6ba77040', 'Fresquito, calentito', '**-ito** and **-cito**: **fresquito**, **solcito**, **calentito**, **igualito**, **una cosita**.', 'draft'),
  ('b1b445dc-605c-502f-a4b3-fc7a72caf676', 'aca6a7bd-05eb-5bcb-a0c0-02cd6ba77040', 'Lo que pasó fue que…', '**Lo que pasó fue que**, **lo que quiero decir es que**, **lo tuyo**, **lo que sea** — and **como dice el dicho**, **cada loco con su tema**.', 'draft'),
  ('1db93231-c31c-5630-a9d7-a5c19c863dd1', '9f441bef-17a2-535a-a539-79a16389ad10', 'Al horno, al pedo', '**Estoy al horno** — *I''m in trouble, I''m toast*. **Qué bajón** — *what a downer*. **Al pedo** — *for nothing, doing nothing*: **fui al pedo**, **estoy al pedo**. And the flat *no way*: **ni en pedo**. Among friends only.', 'draft'),
  ('361c790d-a0af-59b6-8330-323cd924f6a0', '9f441bef-17a2-535a-a539-79a16389ad10', 'Rata, careta, grasa', 'People get labels: a **rata** never pays; a **careta** is a square (or sober, or a phony); **grasa** is tacky. A **manija** is wound up about something: **estoy manija con el recital**. The **cana** is the police. A friend who backs you **te hace la gamba**; one who talks nonsense **manda fruta**.', 'draft'),
  ('12cc7bc4-dabf-5aa7-b1c3-337d0d448d98', '31b7857e-57f3-5f7b-bcef-b36286ed3425', 'Me hizo sentir…', '**Hacer** + infinitive works with any verb: **me hizo sentir como en casa**, **te hace pensar**, **nos hizo llorar a todos**. And people too: **vos me hacés reír**.', 'draft'),
  ('8b879baa-1e7b-5ea3-9967-18510251f924', '31b7857e-57f3-5f7b-bcef-b36286ed3425', '¿De qué te reís?', '**Reírse** with *vos*: **¿de qué te reís?**; with *him*: **se rió**. **¿Lloraste?** For the big laugh: **me morí de risa** — *I died laughing*. A **comedia** gets a **sonrisa**; a sad scene, **lágrimas** and **tristeza**. And people with **sentido del humor** laugh at themselves.', 'draft'),
  ('aedda56a-3aa2-50c2-bee9-a8634c87b168', 'd750cc27-0380-5a63-ae57-c94ac17315e5', 'Cuanto antes lleguemos', 'About what hasn''t happened yet, the verb after **cuanto** goes subjunctive: **cuanto antes lleguemos, mejor**; **cuanto antes reservemos, más barato**; **cuanto más temprano empecemos, antes terminamos**. About what always happens, the normal verb: **cuanto más ganás, más gastás**.', 'draft'),
  ('b9bc5c55-0b39-5996-a6ed-71dd17a76fb0', 'd750cc27-0380-5a63-ae57-c94ac17315e5', 'Tanto mejor', '**Tanto mejor** — *all the better*: **¿no viene nadie? Tanto mejor**. To **evitar** the **hora pico**, you go early; the place **se llena** fast; and leaving early, the day **rinde** — *goes further*.', 'draft'),
  ('2cdd21ad-467f-5fd7-a33c-ff457fb68650', '7957b305-bc76-56e8-b615-86768419c16d', 'Al horno, manija', '**Al horno**, **qué bajón**, **ni en pedo**, **rata**, **careta**, **manija** — among friends.', 'draft'),
  ('2195936f-d3dc-5457-874a-d4ff433f78c3', '7957b305-bc76-56e8-b615-86768419c16d', 'Me morí de risa, tanto mejor', '**Me morí de risa**, **¿de qué te reís?**, **me hizo sentir…** — and **cuanto antes lleguemos, mejor**.', 'draft'),
  ('102ea8d0-6e5a-50b1-816d-8bdb9e099e9b', 'a36e5278-67e4-5dc0-b0ec-7e8440a51419', 'Sin ofender', 'Porteños are direct, but they pad it: **sin ofender** — *no offense*; **te lo digo con cariño**; **no es nada personal**. A **crítica** goes down better that way, above all on a **tema delicado**.', 'draft'),
  ('77148055-5321-5789-a07d-30827fa6d798', 'a36e5278-67e4-5dc0-b0ec-7e8440a51419', 'Perdoname, quise decir…', 'When it lands badly: **perdoname, me expresé mal** — *I put it badly*; **quise decir otra cosa** — *I meant something else*; **no fue mi intención lastimarte**.', 'draft')
